/* Security Market Line interactive */
(function () {
  var svg = document.getElementById("sml-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id, t){ var e = document.getElementById(id); if (e) e.textContent = t; }

  function activeLang(){ return document.body.getAttribute("data-active-lang") || "fr"; }
  var VERD = {
    under: {fr:"Sous-évalué (α > 0)", en:"Under-valued (α > 0)", nl:"Ondergewaardeerd (α > 0)"},
    over:  {fr:"Sur-évalué (α < 0)",  en:"Over-valued (α < 0)",  nl:"Overgewaardeerd (α < 0)"},
    fair:  {fr:"Évalué à sa juste valeur (α ≈ 0)", en:"Fairly valued (α ≈ 0)", nl:"Correct gewaardeerd (α ≈ 0)"}
  };

  function draw() {
    var rf=v("sml-rf"), erm=v("sml-erm"), beta=v("sml-beta"), era=v("sml-era");
    setT("sml-rf-o", v("sml-rf")+"%"); setT("sml-erm-o", v("sml-erm")+"%");
    setT("sml-beta-o", v("sml-beta").toFixed(2)); setT("sml-era-o", v("sml-era")+"%");

    var req = rf + beta*(erm-rf);
    var alpha = era - req;
    setT("sml-req", req.toFixed(2)+"%");
    setT("sml-alpha", (alpha>=0?"+":"")+alpha.toFixed(2)+"%");
    var L = activeLang();
    var vk = Math.abs(alpha) < 0.25 ? "fair" : (alpha>0 ? "under" : "over");
    var vEl = document.getElementById("sml-verdict");
    if (vEl){ vEl.textContent = VERD[vk][L]; vEl.style.color = vk==="under" ? "var(--gold)" : (vk==="over" ? "var(--crimson)" : "var(--ink-mute)"); }

    var W=520,H=340,Lm=48,R=16,T=14,B=34, pw=W-Lm-R, ph=H-T-B;
    var xMax=2.5;
    var yVals=[rf, erm, req, era, rf+xMax*(erm-rf)];
    var yHi=Math.max.apply(null,yVals), yLo=Math.min.apply(null,yVals,[0]);
    yLo=Math.min(yLo,0); var pad=(yHi-yLo)*0.12||1; yHi+=pad; yLo=Math.max(0,yLo);
    function px(x){ return Lm + x/xMax*pw; }
    function py(y){ return T + (yHi-y)/(yHi-yLo)*ph; }

    var g="";
    var nx=5;
    for (var k=0;k<=nx;k++){ var xv=xMax*k/nx, X=px(xv);
      g+='<line class="grid" x1="'+X+'" y1="'+T+'" x2="'+X+'" y2="'+(T+ph)+'"/>';
      g+='<text class="tick" x="'+X+'" y="'+(T+ph+13)+'" text-anchor="middle">'+xv.toFixed(1)+'</text>';
    }
    for (var m=0;m<=4;m++){ var yv=yLo+(yHi-yLo)*m/4, Y=py(yv);
      g+='<line class="grid" x1="'+Lm+'" y1="'+Y+'" x2="'+(Lm+pw)+'" y2="'+Y+'"/>';
      g+='<text class="tick" x="'+(Lm-6)+'" y="'+(Y+3)+'" text-anchor="end">'+yv.toFixed(1)+'</text>';
    }
    g+='<line class="axis" x1="'+Lm+'" y1="'+(T+ph)+'" x2="'+(Lm+pw)+'" y2="'+(T+ph)+'"/>';
    g+='<line class="axis" x1="'+Lm+'" y1="'+T+'" x2="'+Lm+'" y2="'+(T+ph)+'"/>';

    // SML line from beta=0 (rf) to beta=xMax
    g+='<line class="sml" x1="'+px(0)+'" y1="'+py(rf)+'" x2="'+px(xMax)+'" y2="'+py(rf+xMax*(erm-rf))+'"/>';
    // rf point
    g+='<circle class="dot-rf" cx="'+px(0)+'" cy="'+py(rf)+'" r="4"/><text class="alab" x="'+(px(0)+7)+'" y="'+(py(rf)-6)+'">r_f</text>';
    // market point at beta=1
    g+='<circle class="dot-mkt" cx="'+px(1)+'" cy="'+py(erm)+'" r="5"/><text class="alab" x="'+(px(1)+8)+'" y="'+(py(erm)-6)+'">M</text>';
    // asset drop lines + point
    g+='<line class="drop" x1="'+px(beta)+'" y1="'+py(era)+'" x2="'+px(beta)+'" y2="'+py(req)+'"/>';
    g+='<circle class="dot-cur" cx="'+px(beta)+'" cy="'+py(era)+'" r="6"/>';

    g+='<text class="alab" x="'+(Lm+pw/2)+'" y="'+(H-3)+'" text-anchor="middle">β</text>';
    g+='<text class="alab" transform="translate(13,'+(T+ph/2)+') rotate(-90)" text-anchor="middle">E(r) (%)</text>';

    svg.innerHTML=g;
  }

  ["sml-rf","sml-erm","sml-beta","sml-era"].forEach(function(id){
    var e=document.getElementById(id); if(e) e.addEventListener("input", draw);
  });
  // redraw on language change (verdict text)
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
